(49111, 'Psalms 38:2', 'Psalms', 38, 2, 'په خپلو غشو دې زخمي کړمه زه او په خپل لاس باندې دې ووهلم', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms38_verse_2.mp3', '', 1761754199, 1761754199),
(49112, 'Psalms 38:3', 'Psalms', 38, 3, 'زما بدن کې روغ ځای نشته ستا د قهر له لاسه حتی هډوکي مې خوږیږي د ګناه له لاسه', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms38_verse_3.mp3', '', 1761754199, 1761754199),
(49113, 'Psalms 38:4', 'Psalms', 38, 4, 'زه د خپلو ګناهونو په دریاب کې یم ډوب شوی هغه دي دومره درانه چې وړلی یې نه شم', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms38_verse_4.mp3', '', 1761754199, 1761754199),
(49114, 'Psalms 38:5', 'Psalms', 38, 5, 'په سبب زما د خپلې بې‌عقلۍ پرهارونه مې خوسا شول بوی ترې خېژي', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms38_verse_5.mp3', '', 1761754199, 1761754199),
(49115, 'Psalms 38:6', 'Psalms', 38, 6, 'زه کړوپ شوی یمه زه یم ځپل شوی ټوله ورځ زه ویر کومه', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms38_verse_6.mp3', '', 1761754199, 1761754199),
