(49117, 'Psalms 38:8', 'Psalms', 38, 8, 'زه له کاره یم لوېدلی او بیخي یمه مات شوی زما زړه دی ناقراره او له درده زګېروي کړمه', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms38_verse_8.mp3', '', 1761754199, 1761754199),
(49118, 'Psalms 38:9', 'Psalms', 38, 9, 'ای څښتنه، ته پوهېږې چې زه څه ارمان لرمه ټول زګېروي ته زما اورې', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms38_verse_9.mp3', '', 1761754199, 1761754199),
(49119, 'Psalms 38:10', 'Psalms', 38, 10, 'زړه مې درزیږي او قوت رانه لاړ زما د سترګو دید کمزوری شولو', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms38_verse_10.mp3', '', 1761754199, 1761754199),
(49120, 'Psalms 38:11', 'Psalms', 38, 11, 'نه رانژدې کیږي په سبب د ناروغۍ راته ټول زما ملګري او دوستان زما حتی تر دې چې خپل خپلوان هم رانه لېرې ګرځي', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms38_verse_11.mp3', '', 1761754199, 1761754199),
(49121, 'Psalms 38:12', 'Psalms', 38, 12, 'هغوی چې غواړي چې ما مړ کړي راته ږدي دامونه هغوی چې غواړي راته ورسوي زیان د بربادۍ کوي ګواښونه راته ټوله ورځ دوی دسیسې جوړوي او دروغ وایي', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms38_verse_12.mp3', '', 1761754199, 1761754199),
(49122, 'Psalms 38:13', 'Psalms', 38, 13, 'خو زه د هغه کوڼ په شان یم چې څه نه اورمه او د هغه ګونګ په شان یم چې هېڅ نه کوي خبرې', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms38_verse_13.mp3', '', 1761754199, 1761754199),
(49123, 'Psalms 38:14', 'Psalms', 38, 14, 'زه یم د هغه چا په څېر چې خپله دفاع کې نه شي دلیل ویلی ځکه چې نه اوري', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms38_verse_14.mp3', '', 1761754199, 1761754199),
(49124, 'Psalms 38:15', 'Psalms', 38, 15, 'خو تا باندې باور لرم څښتنه او ای زما څښتنه خدایه، راکوې به ته ځواب', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms38_verse_15.mp3', '', 1761754199, 1761754199),
(49125, 'Psalms 38:16', 'Psalms', 38, 16, 'سوال مې وکړ: «مه پرېږده دښمن زما چې وکړي خوشحالي زما په غم باندې مه پرېږده هغوی چې لافې ووهي زما په ناکامۍ او بدبختۍ باندې»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms38_verse_16.mp3', '', 1761754199, 1761754199),
(49126, 'Psalms 38:17', 'Psalms', 38, 17, 'یمه نژدې چې زه راپرېوځمه مدام دي مل راسره زما دردونه', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms38_verse_17.mp3', '', 1761754199, 1761754199),
(49127, 'Psalms 38:18', 'Psalms', 38, 18, 'زه اقرار کوم د خپلو ګناهونو یمه پرېشانه زه د خپلو ګناهونو له امله', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms38_verse_18.mp3', '', 1761754199, 1761754199),
(49128, 'Psalms 38:19', 'Psalms', 38, 19, 'دښمنان زما قوي او صحتمند دي هغوی ډېر دي چې کوي کرکه له ما نه بې‌سببه', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms38_verse_19.mp3', '', 1761754199, 1761754199),
(49129, 'Psalms 38:20', 'Psalms', 38, 20, 'هغه خلک چې بدي کړي د نېکۍ په بدله کې هغوی دي زما په ضد ځکه زه کړمه کوښښ چې نېک کار وکړم', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms38_verse_20.mp3', '', 1761754199, 1761754199),
(49130, 'Psalms 38:21', 'Psalms', 38, 21, 'ته ما مه پرېږده څښتنه لېرې کېږه مه له ما نه زما خدایه!', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms38_verse_21.mp3', '', 1761754199, 1761754199),
(49131, 'Psalms 38:22', 'Psalms', 38, 22, 'زر راشه کومک وکړه زما سره ای څښتنه ته زما یې خلاصوونکی!', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms38_verse_22.mp3', '', 1761754199, 1761754199),
(49132, 'Leviticus 10:1', 'Leviticus', 10, 1, 'د هارون زامنو ناداب او ابیهو هر یو خپل د اور لوښی راواخیست او په هغې کې یې بل شوي سکاره واچول، خوشبویي یې ورزیاته کړه او هغه یې څښتن ته وړاندې کړل. خو دا اور سپېڅلی نه ؤ، ځکه چې څښتن په هغوی باندې د هغه د وړاندې کولو امر نه ؤ کړی.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/leviticus10_verse_1.mp3', '', 1761754199, 1761754199),
(49133, 'Leviticus 10:2', 'Leviticus', 10, 2, 'نو څښتن ناڅاپه اور نازل کړ او هغوی یې په خپل حضور کې وسوځول او مړه شول.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/leviticus10_verse_2.mp3', '', 1761754199, 1761754199),
(49134, 'Leviticus 10:3', 'Leviticus', 10, 3, 'بیا موسی هارون ته وویل: «دا هغه څه دي چې څښتن یې په هکله خبرې کولې او هغه وویل: هغه خلک چې خدمت کوي زما باید وکړي درناوی د سپېڅلتوب زما د ټول قوم په نظر کې به زه دروند یم خو هارون غلی پاتې شو.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/leviticus10_verse_3.mp3', '', 1761754199, 1761754199),
(49135, 'Leviticus 10:4', 'Leviticus', 10, 4, 'موسی میشاییل او الصافان چې د هارون او موسی د تره عزییل زامن وو، راوغوښتل او ورته ویې ویل: «دلته راشئ، د خپل تره د زامنو مړي د سپېڅلي ځای څخه لېرې کړئ او د کمپ څخه دباندې یې یوسئ.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/leviticus10_verse_4.mp3', '', 1761754199, 1761754199),
(49136, 'Leviticus 10:5', 'Leviticus', 10, 5, 'نو هغوی راغلل او څنګه چې موسی حکم کړی ؤ، د هغوی مړي یې د کالیو څخه ونیول او د کمپ څخه یې دباندې یووړل.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/leviticus10_verse_5.mp3', '', 1761754199, 1761754199),
(49137, 'Leviticus 10:6', 'Leviticus', 10, 6, 'بیا موسی هارون او د هغه زامنو العازار او ایتامار ته وویل: «خپل ویښتان ګډوډ مه پرېږدئ او خپل کالي مه شلوئ چې دا وښایي چې تاسو غمجن یئ. که چېرې داسې وکړئ، نو تاسو به مړه شئ او څښتن به په ټول قوم باندې په قهر شي. خو نور ټول اسراییلیان کولای شي چې د هغو دوو کسانو دپاره چې څښتن د اور په وسیله له منځه وړي دي، وژاړي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/leviticus10_verse_6.mp3', '', 1761754199, 1761754199),
(49138, 'Leviticus 10:7', 'Leviticus', 10, 7, 'د خېمې د دروازې د خولې څخه مه ځئ، که نه، نو تاسو به مړه شئ، ځکه چې تاسو د څښتن د مسح کولو په تېلو باندې پاک شوي یئ.» نو څنګه چې موسی ویلي وو، هغوی هماغسې وکړل.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/leviticus10_verse_7.mp3', '', 1761754199, 1761754199),
(49139, 'Leviticus 10:8', 'Leviticus', 10, 8, 'څښتن هارون ته وویل:', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/leviticus10_verse_8.mp3', '', 1761754199, 1761754199),
(49140, 'Leviticus 10:9', 'Leviticus', 10, 9, '«ته او ستا زامن د شرابو د څښلو نه وروسته سپېڅلې خېمې ته مه ورننوځئ، که چېرې داسې وکړئ نو مړه به شئ. دا یو تلپاتې قانون دی چې ستاسو ټوله اولاده به ورباندې عمل کوي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/leviticus10_verse_9.mp3', '', 1761754199, 1761754199),
(49141, 'Leviticus 10:10', 'Leviticus', 10, 10, 'تاسو باید د هغو شیانو ترمنځ چې سپېڅلي او عادي دي، فرق وکړئ او د هغو شیانو ترمنځ چې کوم پاک دي او کوم ناپاک.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/leviticus10_verse_10.mp3', '', 1761754199, 1761754199),
(49142, 'Leviticus 10:11', 'Leviticus', 10, 11, 'باید د اسراییلو قوم ته هغه ټول قوانین ورزده کړئ چې ما تاسو ته د موسی په وسیله درکړي دي.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/leviticus10_verse_11.mp3', '', 1761754199, 1761754199),
(49143, 'Leviticus 10:12', 'Leviticus', 10, 12, 'بیا موسی هارون او د هغه پاتې زامنو العازار او ایتامار ته وویل: «د غلې دانې هغه نذرانه چې څښتن ته په اور باندې د تیارېدونکو نذرانو څخه پاتې شوې ده واخلئ، د هغې څخه فطیره ډوډۍ پخه کړئ او د قربانۍ د ځای په څنګ کې یې وخورئ، ځکه چې دا نذرانه ډېره سپېڅلې ده.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/leviticus10_verse_12.mp3', '', 1761754199, 1761754199),
(49144, 'Leviticus 10:13', 'Leviticus', 10, 13, 'هغه په یو سپېڅلي ځای کې وخورئ، ځکه چې دا ستا او ستا د زامنو د هغو نذرانو برخه ده چې څښتن ته په اور باندې تیاریږي. دا هغه څه دي چې څښتن یې ماته امر کړی دی.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/leviticus10_verse_13.mp3', '', 1761754199, 1761754199),
(49145, 'Leviticus 10:14', 'Leviticus', 10, 14, 'خو سینه او شاتنۍ پښه چې پورته نیول کیږي، هغه دې په داسې ځای کې چې په مذهبي لحاظ پاک وي، وخوړل شي. دا برخه تاسو، ستاسو زامنو او لورګانو ته ستاسو د برخې په توګه د سلامتۍ د هغو نذرانو څخه چې د اسراییلو د خلکو له خوا وړاندې کیږي، درکول کیږي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/leviticus10_verse_14.mp3', '', 1761754199, 1761754199),
(49146, 'Leviticus 10:15', 'Leviticus', 10, 15, 'شاتنۍ پښه او سینه باید د هغو نذرانو د وازګې سره چې په اور باندې تیاریږي، څښتن ته پورته ونیول شي. بیا لکه څنګه چې څښتن حکم کړی دی، هغه به د تل دپاره ستاسو او ستاسو د اولادې برخه وي.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/leviticus10_verse_15.mp3', '', 1761754199, 1761754199),
(49147, 'Leviticus 10:16', 'Leviticus', 10, 16, 'موسی د هغه سېرلي په اړه پوښتنه وکړه چې د ګناه د نذرانې دپاره ؤ او خبر شو چې هغه سوځول شوی دی. په دې خبره هغه په العازار او ایتامار باندې په قهر شو او پوښتنه یې وکړه:', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/leviticus10_verse_16.mp3', '', 1761754199, 1761754199),
(49148, 'Leviticus 10:17', 'Leviticus', 10, 17, '«تاسو ولې د ګناه نذرانه په یو سپېڅلي ځای کې ونه خوړله؟ هغه ډېره سپېڅلې ده او څښتن د دې دپاره تاسو ته درکړې وه چې د کفارې په ادا کولو سره د قوم څخه ګناه لېرې شي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/leviticus10_verse_17.mp3', '', 1761754199, 1761754199),
(49149, 'Leviticus 10:18', 'Leviticus', 10, 18, 'په دې خاطر چې د هغه وینه سپېڅلې خېمې ته نه وه وړل شوې، نو تاسو باید د سېرلي غوښه هلته خوړلې وای، لکه څنګه چې ما درته امر کړی ؤ.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/leviticus10_verse_18.mp3', '', 1761754199, 1761754199),
(49150, 'Leviticus 10:19', 'Leviticus', 10, 19, 'هارون په ځواب کې وویل: «که چېرې ما د ګناه نذرانه نن خوړلې وای، ایا څښتن به هغه قبوله کړې وای؟ قوم خپله د ګناه نذرانه نن څښتن ته وړاندې کړه او خپله سوځېدونکې نذرانه یې راوړله، خو بیاهم په ما باندې دا هیبتناکه پېښې وشوې.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/leviticus10_verse_19.mp3', '', 1761754199, 1761754199),
(49151, 'Leviticus 10:20', 'Leviticus', 10, 20, 'کله چې موسی دا خبرې واورېدلې، هغه قانع شو.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/leviticus10_verse_20.mp3', '', 1761754199, 1761754199),
(49152, 'Numbers 24:1', 'Numbers', 24, 1, 'بلعام په دې یقین درلود چې څښتن به ورته ووایي چې اسراییلیانو ته بیا برکت ورکړه. نو هغه د فال څخه هېڅ کار وانخیست چې معلومه کړي څښتن د هغه څخه څه غواړي چې ویې کړي، لکه څنګه یې چې دوه ځلې مخکې کړي وو. د دې په ځای یې د دښتې خواته وکتل', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers24_verse_1.mp3', '', 1761754199, 1761754199),
(49153, 'Numbers 24:2', 'Numbers', 24, 2, 'او د اسراییلو خلک یې ولیدل چې قبیله په قبیله یې خېمې ودرولې وې. بیا د خدای روح په هغه باندې نازل شو', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers24_verse_2.mp3', '', 1761754199, 1761754199),
(49154, 'Numbers 24:3', 'Numbers', 24, 3, 'او بلعام دا پیغام ورکړ: «د بعور د زوی بلعام پیغام دی د هغه چا خبرې چې سترګې یې خلاصې شولې', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers24_verse_3.mp3', '', 1761754199, 1761754199),
(49155, 'Numbers 24:4', 'Numbers', 24, 4, 'چې اورېدلی شي خبرې د خدای څوک چې رویا ویني د مطلق قادر خدای له خوا څوک چې پړمخې پرېوځي او خلاصې یې دي سترګې', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers24_verse_4.mp3', '', 1761754199, 1761754199),
(49156, 'Numbers 24:5', 'Numbers', 24, 5, 'د اسراییلو قومه ستاسو کمپ دی څومره ښکلی', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers24_verse_5.mp3', '', 1761754199, 1761754199),
(49157, 'Numbers 24:6', 'Numbers', 24, 6, 'د خرماګانو د اوږدو قطارونو په شان د سیند په غاړه د باغونو په شان چې دي کرلي څښتن د عود د ونو په شان د سیند په غاړه د سبر د ونو په شان', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers24_verse_6.mp3', '', 1761754199, 1761754199),
(49158, 'Numbers 24:7', 'Numbers', 24, 7, 'وي به په دوی باندې پرېمانه باران په ابي ځمکو کې کري به خپل تخمونه له اجاج څخه به لوی د دوی پاچا وي وي به سرلوړې پاچاهي د هغه', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers24_verse_7.mp3', '', 1761754199, 1761754199),
(49159, 'Numbers 24:8', 'Numbers', 24, 8, 'خدای دوی راوویستل له مصر څخه په ډېر قوت سره جنګیږي دی هغوی دپاره د ځنګلي غویي په شان خپل دښمنان تباه کوي هغه ماتوي د دوی هډوکي او په غشو هغوی ولي', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers24_verse_8.mp3', '', 1761754199, 1761754199),
(49160, 'Numbers 24:9', 'Numbers', 24, 9, 'دغه قوم دی د قوي زمري په شان چې ویده وي هېڅوک نه شي کړای جرات چې راویښ کړي هغه په هغو به برکت وي څوک چې وایي برکت په اسراییلو وي لعنت به په هغوی چې لعنت په اسراییلو باندې وایي»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers24_verse_9.mp3', '', 1761754199, 1761754199),
(49161, 'Numbers 24:10', 'Numbers', 24, 10, 'کله چې بالاق دا واورېدل، نو د قهره یې خپل لاسونه سره ومروړل او ویې ویل: «ما د دې دپاره راوغوښتلې چې زما په دښمنانو باندې لعنت ووایې، خو تا هغوی ته درې ځلې برکت ورکړ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers24_verse_10.mp3', '', 1761754199, 1761754199),
(49162, 'Numbers 24:11', 'Numbers', 24, 11, 'اوس ځه ورک شه، خپل کور ته لاړ شه! ما ستا سره وعده کړې وه چې ښه انعام به درکړم، خو څښتن ورڅخه بې برخې کړې.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers24_verse_11.mp3', '', 1761754199, 1761754199),
(49163, 'Numbers 24:12', 'Numbers', 24, 12, 'بلعام په ځواب کې وویل: «ما ستا استازو ته چې ماته دې رالېږلي وو، ویلي وو', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers24_verse_12.mp3', '', 1761754199, 1761754199),
(49164, 'Numbers 24:13', 'Numbers', 24, 13, 'چې حتی که چېرې ته ماته خپله ماڼۍ چې د سرو زرو او سپینو زرو څخه ډکه ده هم راکړې، بیاهم زه نه شم کولای چې د څښتن د امر په خلاف کوم کار وکړم. زه به یوازې هغه څه وایم چې څښتن یې راته وایي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers24_verse_13.mp3', '', 1761754199, 1761754199),
(49165, 'Numbers 24:14', 'Numbers', 24, 14, 'اوس زه بېرته خپلو خلکو ته ورځم، خو مخکې له دې چې لاړ شم، زه تاته د هغه څه په هکله یو خبرداری درکوم چې اسراییلیان به یې یوه ورځ ستا د قوم سره وکړي.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers24_verse_14.mp3', '', 1761754199, 1761754199),
(49166, 'Numbers 24:15', 'Numbers', 24, 15, 'بیا بلعام دا پیغام ورکړ: د بعور د زوی بلعام پیغام دی د هغه چا خبرې چې سترګې یې خلاصې شولې', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers24_verse_15.mp3', '', 1761754199, 1761754199),
(49167, 'Numbers 24:16', 'Numbers', 24, 16, 'چې اورېدلی شي خبرې د خدای او هغه پوهه مومي د خدای تعالی له خوا نه څوک چې رویا ویني د مطلق قادر خدای له خوا څوک چې پړمخې پرېوځي او خلاصې یې دي سترګې', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers24_verse_16.mp3', '', 1761754199, 1761754199),
(49168, 'Numbers 24:17', 'Numbers', 24, 17, 'خپلې رویا کې چې ما لیدلي دي څه پېښ شوي نه دي لا تر اوسه پورې خو یوه ورځ به راښکاره شي لکه ستوري په شان د اسراییلو پاچا هغه به تاسو موآبیان ورک کړي او د شیت ټول قوم به له منځه یوسي', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers24_verse_17.mp3', '', 1761754199, 1761754199),
(49169, 'Numbers 24:18', 'Numbers', 24, 18, 'هغه به ومومي بری په دښمنانو په ادوم کې او د هغوی خاوره به کړي خپل ملکیت خو قوي به اسراییل شي', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers24_verse_18.mp3', '', 1761754199, 1761754199),
(49170, 'Numbers 24:19', 'Numbers', 24, 19, 'پاچاهي به وکړي د اسراییلو پاچا د هر ښار پاتې شوي ژوندي خلک به له منځه یوسي', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers24_verse_19.mp3', '', 1761754199, 1761754199),
(49171, 'Numbers 24:20', 'Numbers', 24, 20, 'بیا بلعام په خپله رویا کې عمالیقیان ولیدل او دا پیغام یې ورکړ: عمالیق دی ډېر قوي ټولو قومونو څخه خو په اخر کې به له منځه لاړ شي هغه د تل دپاره', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers24_verse_20.mp3', '', 1761754199, 1761754199),
(49172, 'Numbers 24:21', 'Numbers', 24, 21, 'هغه په خپله رویا کې قینیان ولیدل او دا پیغام یې ورکړ: ستاسو ځای د اوسېدلو دی په امن داسې امن لکه ځاله چې وي جوړه په ګټ باندې', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers24_verse_21.mp3', '', 1761754199, 1761754199),
(49173, 'Numbers 24:22', 'Numbers', 24, 22, 'خو تباه به شئ تاسو قینیان چې کله تاسو اسیران کړي آشوریان', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers24_verse_22.mp3', '', 1761754199, 1761754199),
(49174, 'Numbers 24:23', 'Numbers', 24, 23, 'بلعام دغه پیغام ورکړ: هېڅوک ژوندی پاتې کېدلی نه شي که خدای پلان د تباهۍ ولري', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers24_verse_23.mp3', '', 1761754199, 1761754199),
(49175, 'Numbers 24:24', 'Numbers', 24, 24, 'رابه شي د قبرس له سواحله کشتۍ ګانې رابه وړي خلک چې کړي فتح آشور او عیبر خو په اخر کې به قبرس په خپله هم برباد شي', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers24_verse_24.mp3', '', 1761754199, 1761754199),
(49176, 'Numbers 24:25', 'Numbers', 24, 25, 'بیا بلعام راپاڅېده او بېرته خپل کور ته روان شو او بالاق هم لاړ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers24_verse_25.mp3', '', 1761754199, 1761754199),
(49177, 'Psalms 147:1', 'Psalms', 147, 1, 'د څښتن ثنا او صفت وکړئ څومره ښه ده چې خپل خدای دپاره ووایو سندره څومره خوشحالوونکې او سمه ده چې صفت یې وکړو', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms147_verse_1.mp3', '', 1761754199, 1761754199),
(49178, 'Psalms 147:2', 'Psalms', 147, 2, 'څښتن بیا ابادوي اورشلیم شړلي خلک د اسراییلو راولي بېرته خپل کور ته', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms147_verse_2.mp3', '', 1761754199, 1761754199),
(49179, 'Psalms 147:3', 'Psalms', 147, 3, 'روغوي هغه مات زړونه او ږدي پټۍ د دوی زخمونو باندې', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms147_verse_3.mp3', '', 1761754199, 1761754199),
(49180, 'Psalms 147:4', 'Psalms', 147, 4, 'هغه ټاکلی دی د ستورو شمېر او هر یوه ته یې خپل نوم ورکړی', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms147_verse_4.mp3', '', 1761754199, 1761754199),
(49181, 'Psalms 147:5', 'Psalms', 147, 5, 'زمونږ څښتن دی لوی او ډېر زورور دی هغه بې‌اندازې ده د هغه پوهه', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms147_verse_5.mp3', '', 1761754199, 1761754199),
(49182, 'Psalms 147:6', 'Psalms', 147, 6, 'پورته کوي څښتن عاجزان خلک خو بدکاران راغورځوي په ځمکه', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms147_verse_6.mp3', '', 1761754199, 1761754199),
(49183, 'Psalms 147:7', 'Psalms', 147, 7, 'څښتن ته ووایئ د شکرګزارۍ سندره وغږوئ ساز خپل خدای ته په رباب سره', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms147_verse_7.mp3', '', 1761754199, 1761754199),
(49184, 'Psalms 147:8', 'Psalms', 147, 8, 'هغه په ورېځو پټوي اسمان را‌اوروي هغه باران په ځمکه او شنه کوي واښه غونډیو باندې', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms147_verse_8.mp3', '', 1761754199, 1761754199),
(49185, 'Psalms 147:9', 'Psalms', 147, 9, 'حیواناتو ته خوراک رسوي ورکوي خوراک چې کله وچغیږي د کارغانو بچي', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms147_verse_9.mp3', '', 1761754199, 1761754199),
(49186, 'Psalms 147:10', 'Psalms', 147, 10, 'د هغه خوشحالي نه ده د اس قوت کې او نه یې خوښي شته د انسان طاقت کې', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms147_verse_10.mp3', '', 1761754199, 1761754199),
(49187, 'Psalms 147:11', 'Psalms', 147, 11, 'خو څښتن خوشحاله وي د هغو خلکو څخه چې کړي وېره له هغه او څوک چې باور لري د هغه په تلپاتې مینه', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms147_verse_11.mp3', '', 1761754199, 1761754199),
(49188, 'Psalms 147:12', 'Psalms', 147, 12, 'ای اورشلیمه، د څښتن ثنا او صفت وکړه ای صهیونه، د خپل خدای ثنا او صفت وکړه', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms147_verse_12.mp3', '', 1761754199, 1761754199),
(49189, 'Psalms 147:13', 'Psalms', 147, 13, 'ځکه قوي ساتي اړمونه ستا د ښار د دروازو او برکت ورکوي ستا اوسېدونکو ته', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms147_verse_13.mp3', '', 1761754199, 1761754199),
(49190, 'Psalms 147:14', 'Psalms', 147, 14, 'ستا سرحدونه په امان کې ساتي او مړوي تا په ډېرو ښو غنمو باندې', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms147_verse_14.mp3', '', 1761754199, 1761754199),
(49191, 'Psalms 147:15', 'Psalms', 147, 15, 'هغه امر کوي ځمکې ته او څه چې وایي اجرا کیږي هغه زر', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms147_verse_15.mp3', '', 1761754199, 1761754199),
(49192, 'Psalms 147:16', 'Psalms', 147, 16, 'وروي واوره لکه سپینو وړیو په شان او خپروي پرخه لکه ایرې په شان', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms147_verse_16.mp3', '', 1761754199, 1761754199),
(49193, 'Psalms 147:17', 'Psalms', 147, 17, 'هغه ږلۍ وروي لکه د کاڼو په شان څوک ټینګېدلی نه شي د هغه یخنۍ ته', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms147_verse_17.mp3', '', 1761754199, 1761754199),
(49194, 'Psalms 147:18', 'Psalms', 147, 18, 'د هغه په حکم ویلي کیږي یخ رالېږي بادونه او جاري کیږي اوبه', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms147_verse_18.mp3', '', 1761754199, 1761754199),
(49195, 'Psalms 147:19', 'Psalms', 147, 19, 'هغه یعقوب ته خپل پیغام ورکوي یعنې اسراییلو ته خپل قوانین او احکام', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms147_verse_19.mp3', '', 1761754199, 1761754199),
(49196, 'Psalms 147:20', 'Psalms', 147, 20, 'هغه بل قوم ته داسې نه دي کړي دوی نه پوهیږي د هغه په قوانینو باندې د څښتن ثنا او صفت وکړئ', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms147_verse_20.mp3', '', 1761754199, 1761754199),
(49197, 'Numbers 13:1', 'Numbers', 13, 1, 'څښتن موسی ته وویل:', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers13_verse_1.mp3', '', 1761754199, 1761754199),
(49198, 'Numbers 13:2', 'Numbers', 13, 2, '«د هرې قبیلې څخه یو یو مشر غوره کړه او کنعان ته یې د جاسوسانو په توګه ولېږه چې هغه وطن وګوري چې زه یې اسراییلیانو ته ورکوم.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers13_verse_2.mp3', '', 1761754199, 1761754199),
(49199, 'Numbers 13:3', 'Numbers', 13, 3, 'نو موسی د څښتن د حکم سره سم د فاران د دښتې څخه دولس قبیلوي مشران ولېږل', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers13_verse_3.mp3', '', 1761754199, 1761754199),
(49200, 'Numbers 13:17', 'Numbers', 13, 17, 'مخکې له دې چې موسی هغوی کنعان ته ولېږي، داسې یې ورته وویل: «کله چې د کنعان د جنوبي دښتې څخه تېر شوئ، غرنۍ سیمې ته چې په شمال کې ده لاړ شئ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers13_verse_17.mp3', '', 1761754199, 1761754199),
(49201, 'Numbers 13:18', 'Numbers', 13, 18, 'دا معلومه کړئ چې هغه هېواد څه ډول دی، په هغه ځای کې څومره خلک اوسیږي او هغوی څومره قوي دي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers13_verse_18.mp3', '', 1761754199, 1761754199),
(49202, 'Numbers 13:19', 'Numbers', 13, 19, 'هغه ځمکه ښه ده یا خرابه او ایا خلک په بې دېواله ښارونو کې اوسیږي یا په دېوال لرونکو ښارونو کې؟', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers13_verse_19.mp3', '', 1761754199, 1761754199),
(49203, 'Numbers 13:20', 'Numbers', 13, 20, 'خاوره یې حاصلخېزه ده او یا ځمکه یې ځنګلي ده؟ د هغو مېوو څخه چې هلته پیدا کیږي لږه خامخا د ځان سره راوړئ.» (دا د لومړنیو پخو شویو انګورو موسم ؤ.)', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers13_verse_20.mp3', '', 1761754199, 1761754199),
(49204, 'Numbers 13:21', 'Numbers', 13, 21, 'نو کسان د شمال خواته لاړل او هغه ځمکه یې د صین د دښتې څخه چې په جنوب کې وه تر رحوب پورې چې په شمال کې د حمات غاښي ته نژدې وه، وکتله.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers13_verse_21.mp3', '', 1761754199, 1761754199),
(49205, 'Numbers 13:22', 'Numbers', 13, 22, 'هغوی لومړی د هغه وطن جنوبي برخې ته لاړل او حبرون ته ورغلل. هلته د اخیمان، شیشای او تلمای طایفې اوسېدلې، دا د عناقیانو د قوم اولاده وه، چې ډېر لوړ قدونه یې درلودل. (حبرون اووه کاله مخکې د صوعن څخه چې په مصر کې ؤ، جوړ شوی ؤ.)', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers13_verse_22.mp3', '', 1761754199, 1761754199),
(49206, 'Numbers 13:23', 'Numbers', 13, 23, 'هغوی د اشکول درې ته ورغلل او هلته یې یوه څانګه پرې کړه چې د انګورو یو وږی په کې ؤ او دومره درنده وه چې دوه تنو هغه د یوې میلې په وسیله انتقال کړه. هغوی لږ انار او انځر هم راوړل.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers13_verse_23.mp3', '', 1761754199, 1761754199),
(49207, 'Numbers 13:24', 'Numbers', 13, 24, 'د انګورو د وږي له امله چې اسراییلیانو هلته پرې کړ، هغه ځای د اشکول د درې په نوم یاد شو.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers13_verse_24.mp3', '', 1761754199, 1761754199),
(49208, 'Numbers 13:25', 'Numbers', 13, 25, 'د کنعان د خاورې د کتلو څخه وروسته چې څلوېښت ورځې یې دوام وموند،', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers13_verse_25.mp3', '', 1761754199, 1761754199),
(49209, 'Numbers 13:26', 'Numbers', 13, 26, 'هغه دولس کسان قادش ته چې د فاران په دښته کې ؤ، راستانه شول او څه یې چې لیدلي وو، موسی، هارون او د اسراییلو ټول قوم ته وویل او هغه مېوه چې هغوی راوړې وه هغوی ته یې وروښودله.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers13_verse_26.mp3', '', 1761754199, 1761754199),
(49210, 'Numbers 13:27', 'Numbers', 13, 27, 'هغوی موسی ته وویل: «مونږ هغه ځمکه وکتله او معلومه شوه چې هغه غني او حاصلخېزه ده او دا د هغې ځمکې لږه مېوه ده.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers13_verse_27.mp3', '', 1761754199, 1761754199);